import React from 'react';
import ReactDOM from 'react-dom';
import { Cascader } from '@alifd/next';
import 'antd/dist/antd.css'; // 或者引入 @alifd/next 的样式

// 构造一个过长的 label
const dataSource = [
  {
    value: '01',
    label: '01-产品接入测试在南天门配置商品遇到问题反馈',
    children: [
      {
        value: '01-1',
        label: '详细问题描述也非常非常长，需要查看完整文本才能明白',
      },
    ],
  },
  {
    value: '02',
    label: '02-线上问题',
    children: [],
  },
];

class Demo extends React.Component {
  render() {
    return (
      <div style={{ padding: 20 }}>
        <h3>默认 Cascader（会出现 title tooltip）</h3>
        <Cascader
          dataSource={dataSource}
          expandTriggerType="hover"
          canOnlySelectLeaf
          // 限制宽度触发文本省略
          listStyle={{ width: 150, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}
        />
      </div>
    );
  }
}

const mountNode = document.getElementById('root') || document.body;
ReactDOM.render(<Demo />, mountNode);
